window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6d02258b4046e6a7"]={"versions": [{"id": "FIG-6d02258b4046e6a7", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Ressourcen-Metamodells in AUTOSAR (ResourceTemplateECU). Das Diagramm modelliert die strukturellen Zusammenhänge und Spezialisierungen von Hardware-Verbindungen (<code>HWConnection</code>) und Hardware-Ports (<code>HWPort</code>) mit speziellem Fokus auf speicherabgebildete Verbindungen (<code>MemoryMappedAssemblyHWConnection</code> und <code>MemoryMappedDelegationHWConnection</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\"><li><strong>HWPort</strong> (spezialisiert <code>Identifiable</code>): Repräsentiert einen Hardware-Anschluss mit dem Attribut <code>+ direction: Enumeration{in, out, inout}</code>.\n</li><li><strong>HWConnection</strong> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für Hardware-Verbindungsstrukturen.\n</li><li><strong>DelegationHWConnection</strong>: Erbt von <code>HWConnection</code>. Bindet über zwei gerichtete Assoziationen an <code>HWPort</code> an:\n<ul class=\"fig-list\"><li>Rolle <code>+OUTER-PORT</code> mit Multiplizität 1 (am HWPort) zu 1 (an DelegationHWConnection).\n</li><li>Rolle <code>+INNER-PORT</code> mit Multiplizität 1 (am HWPort) zu 1 (an DelegationHWConnection).\n</li></ul>\n</li><li><strong>MemoryMappedDelegationHWConnection</strong>: Spezialisiert <code>DelegationHWConnection</code> ohne zusätzliche Attribute.\n</li><li><strong>AssemblyHWConnection</strong>: Erbt von <code>HWConnection</code>. Referenziert <code>HWPort</code> über eine gerichtete Assoziation mit Rollenbezeichnung <code>+hwPort</code> und Multiplizität <code>2..*</code> (am HWPort) zu <code>1</code> (an AssemblyHWConnection).\n</li><li><strong>MemoryMappedAssemblyHWConnection</strong>: Spezialisiert <code>AssemblyHWConnection</code> und deklariert die Attribute:\n<ul class=\"fig-list\"><li><code>+ baseAddress: Int [0..1]</code>\n</li><li><code>+ segmentUsage: Enumeration{code, data, stack, boot} [0..*]</code>\n</li><li><code>+ byteOrder: Enumeration{LittleEndian, BigEndian} [0..1]</code>\n</li><li><code>+ cachable: Boolean [0..1]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm beschreibt eine rein statische Metamodellstruktur für die Hardware-Ressourcenbeschreibung. Ein dynamisches Verhalten oder Sequenzabläufe zur Laufzeit sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen definieren die formale Modellierung von Hardware-Kopplungen auf ECU-Ebene:</p>\n<ul class=\"fig-list\"><li>Eine <code>AssemblyHWConnection</code> verbindet mindestens zwei Hardware-Ports (<code>2..*</code>).\n</li><li>Die Spezialisierung <code>MemoryMappedAssemblyHWConnection</code> spezifiziert Adressierungs- und Zugriffsattribute (<code>baseAddress</code>, <code>byteOrder</code>, Caching-Verhalten und Segmentnutzung) für speicherabgebildete Hardware-Komponenten.\n</li><li>Eine <code>DelegationHWConnection</code> bildet eine hierarchische Brücke zwischen genau einem äußeren Port (<code>+OUTER-PORT</code>, Multiplizität 1) und genau einem inneren Port (<code>+INNER-PORT</code>, Multiplizität 1).\n</li></ul>"}, {"id": "FIG-863bce0cb9a00179", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Ressourcen-Metamodells in AUTOSAR (ResourceTemplateECU). Das Diagramm modelliert die strukturellen Zusammenhänge und Spezialisierungen von Hardware-Verbindungen (<code>HWConnection</code>) und Hardware-Ports (<code>HWPort</code>) mit speziellem Fokus auf speicherabgebildete Verbindungen (<code>MemoryMappedAssemblyHWConnection</code> und <code>MemoryMappedDelegationHWConnection</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\"><li><strong>HWPort</strong> (spezialisiert <code>Identifiable</code>): Repräsentiert einen Hardware-Anschluss mit dem Attribut <code>+ direction: Enumeration{in, out, inout}</code>.\n</li><li><strong>HWConnection</strong> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für Hardware-Verbindungsstrukturen.\n</li><li><strong>DelegationHWConnection</strong>: Erbt von <code>HWConnection</code>. Bindet über zwei gerichtete Assoziationen an <code>HWPort</code> an:\n<ul class=\"fig-list\"><li>Rolle <code>+OUTER-PORT</code> mit Multiplizität 1 (am HWPort) zu 1 (an DelegationHWConnection).\n</li><li>Rolle <code>+INNER-PORT</code> mit Multiplizität 1 (am HWPort) zu 1 (an DelegationHWConnection).\n</li></ul>\n</li><li><strong>MemoryMappedDelegationHWConnection</strong>: Spezialisiert <code>DelegationHWConnection</code> ohne sichtbare Attribute.\n</li><li><strong>AssemblyHWConnection</strong>: Erbt von <code>HWConnection</code>. Referenziert <code>HWPort</code> über eine gerichtete Assoziation mit Rollenbezeichnung <code>+hwPort</code> und Multiplizität <code>2..*</code> (am HWPort) zu <code>1</code> (an AssemblyHWConnection).\n</li><li><strong>MemoryMappedAssemblyHWConnection</strong>: Spezialisiert <code>AssemblyHWConnection</code>. Der Attributbereich der Klasse ist am unteren Bildrand abgeschnitten, wobei lediglich das obere Attributfragment <code>+ baseAddress: Int [0..1]</code> ansatzweise sichtbar ist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Klassendiagramm beschreibt eine rein statische Metamodellstruktur für die Hardware-Ressourcenbeschreibung. Ein dynamisches Verhalten oder Sequenzabläufe zur Laufzeit sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen definieren die formale Modellierung von Hardware-Kopplungen auf ECU-Ebene:</p>\n<ul class=\"fig-list\"><li>Eine <code>AssemblyHWConnection</code> verbindet mindestens zwei Hardware-Ports (<code>2..*</code>).\n</li><li>Die Spezialisierung <code>MemoryMappedAssemblyHWConnection</code> spezifiziert Adressierungs- und Zugriffsattribute (<code>baseAddress</code>, <code>byteOrder</code>, Caching-Verhalten und Segmentnutzung) für speicherabgebildete Hardware-Komponenten.\n</li><li>Eine <code>DelegationHWConnection</code> bildet eine hierarchische Brücke zwischen genau einem äußeren Port (<code>+OUTER-PORT</code>, Multiplizität 1) und genau einem inneren Port (<code>+INNER-PORT</code>, Multiplizität 1).\n</li></ul>"}], "trans": [{"from": "FIG-6d02258b4046e6a7", "to": "FIG-863bce0cb9a00179", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Klassenattribut-Bereich von <code>MemoryMappedAssemblyHWConnection</code>: Die Attribute <code>baseAddress: Int [0..1]</code>, <code>segmentUsage: Enumeration{code, data, stack, boot} [0..*]</code>, <code>byteOrder: Enumeration{LittleEndian, BigEndian} [0..1]</code> und <code>cachable: Boolean [0..1]</code> sind am unteren Bildrand vertikal abgeschnitten bzw. aus dem sichtbaren Darstellungsbereich herausgefallen.\n</li><li>Klasse <code>Identifiable</code> oben rechts: Typografisches Leerzeichen vor <code>Identifiable</code> entfernt.\n</li></ul>"}]};
